"""Websockets Channel for Rasa Voicebot Integration.

This channel provides WebSocket-based audio streaming for mobile applications
(iOS and Android).

Client-supplied data (for example a per-user auth token) can be attached when
the socket is opened and is carried into every user turn's metadata under
``extra`` (see `WebsocketsInputChannel.get_metadata`). Custom responses are
sent to the client as data frames rather than spoken (see
`WebsocketsOutputChannel.send_custom_json`).

Actions that need the connect-time values can read
``tracker.latest_message["metadata"]["extra"]`` or
``tracker.get_slot("session_started_metadata")["extra"]``.
"""

from __future__ import annotations

import base64
import json
import uuid
from typing import Any, Dict, Optional, Union

import structlog
from sanic import (  # type: ignore[attr-defined]
    Blueprint,
    HTTPResponse,
    Request,
    Websocket,
    response,
)
from sanic.exceptions import WebsocketClosed

from rasa.core.channels.channel import RuntimeAgent
from rasa.core.channels.voice_ready.utils import CallParameters
from rasa.core.channels.voice_stream.audio_bytes import (
    L16_24KHZ,
    RasaAudioBytes,
)
from rasa.core.channels.voice_stream.call_state import (
    BotIsSpeaking,
    BotStoppedSpeaking,
    Marker,
    MarkerType,
    call_state,
)
from rasa.core.channels.voice_stream.tts.tts_engine import TTSEngine
from rasa.core.channels.voice_stream.util import repack_voice_credentials
from rasa.core.channels.voice_stream.voice_channel import (
    ContinueConversationAction,
    EndConversationAction,
    MarkerInput,
    MarkerMessageOutput,
    NewAudioAction,
    TextInputAction,
    VoiceChannelAction,
    VoiceInputChannel,
    VoiceOutputChannel,
)

logger = structlog.get_logger()

AUTHORIZATION_HEADER = "Authorization"
AUTHORIZATION_METADATA_KEY = "authorization"
LANGUAGE_QUERY_ARG = "language"


class WebsocketsOutputChannel(VoiceOutputChannel):
    """Output channel for Websockets Voice streaming (iOS and Android)."""

    @classmethod
    def name(cls) -> str:
        return "websockets_voice"

    def rasa_audio_bytes_to_channel_bytes(
        self, rasa_audio_bytes: RasaAudioBytes
    ) -> bytes:
        """Convert Rasa audio bytes to 24kHz L16 format."""
        return rasa_audio_bytes.data

    def channel_bytes_to_message(self, recipient_id: str, channel_bytes: bytes) -> str:
        """Wrap audio bytes in a JSON message for WebSocket transmission."""
        return json.dumps({"audio": base64.b64encode(channel_bytes).decode("utf-8")})

    async def send_custom_json(
        self, recipient_id: str, json_message: Dict[str, Any], **kwargs: Any
    ) -> None:
        """Sends a custom action's JSON payload to the client as a data frame.

        Overrides the base implementation, which stringifies the payload into
        `send_text_message` and would therefore have the assistant read it
        aloud. Sending it as a `custom` frame instead lets an action signal the
        app silently -- for example telling it to refresh an expired token
        after a backend rejected the current one.

        Args:
            recipient_id: The conversation the payload belongs to. Unused: the
                socket already belongs to exactly one conversation.
            json_message: The payload from the action's `custom` response.
            kwargs: Any remaining response fields, ignored by this channel.
        """
        try:
            await self.voice_websocket.send(json.dumps({"custom": json_message}))
        except WebsocketClosed:
            # The caller hung up mid-turn. Flag it and let the channel tear the
            # session down rather than failing the action that sent this.
            call_state.connection_failed = True
            logger.debug("websockets_voice.send_custom_json.connection_closed")

    def create_marker_message(self, marker_input: MarkerInput) -> MarkerMessageOutput:
        """Create a marker message for stream position tracking."""
        marker_id = uuid.uuid4().hex

        if marker_input.marker_type in {MarkerType.START, MarkerType.END}:
            marker = Marker(
                marker_id=marker_id,
                marker_type=marker_input.marker_type,
                step_type=marker_input.step_type,
            )
            call_state.set_marker(marker)

        return MarkerMessageOutput(
            message_id=marker_id,
            message=json.dumps({"marker": marker_id}),
        )


class WebsocketsInputChannel(VoiceInputChannel):
    """Input channel for Websockets Voice streaming (iOS and Android)."""

    requires_voice_license = False

    def __init__(
        self,
        server_url: str,
        asr_config: Dict[str, Any],
        tts_config: Dict[str, Any],
        interruptions: Optional[Dict[str, int]] = None,
        silence_timeout: Optional[Union[float, int]] = None,
    ) -> None:
        """Initialize the Websockets Voice input channel.

        Args:
            server_url: The URL of the Rasa server.
            asr_config: Configuration for the ASR engine.
            tts_config: Configuration for the TTS engine.
            interruptions: Configuration for interruption handling.
            silence_timeout: Timeout for silence detection.
        """
        super().__init__(server_url, asr_config, tts_config, interruptions)
        self.audio_format = L16_24KHZ
        self.silence_timeout = silence_timeout

    @classmethod
    def name(cls) -> str:
        return "websockets_voice"

    def channel_bytes_to_rasa_audio_bytes(self, input_bytes: bytes) -> RasaAudioBytes:
        """Convert Websockets Voice bytes to Rasa audio format (24kHz L16)."""
        return RasaAudioBytes(input_bytes, format=self.audio_format)

    def get_metadata(self, request: Request) -> Optional[Dict[str, Any]]:
        """Extracts client-supplied data from the WebSocket upgrade request.

        Mirrors the REST channel's hook of the same name so app developers get
        the same mechanism on voice: whatever the client attaches when opening
        the socket is carried into every user turn's metadata.

        Collected from the upgrade request:

        - the ``Authorization`` header, so an app can pass a per-user token the
          way it already does on REST
        - any query argument other than ``language``, which the channel handles
          separately as the call's language

        This only *forwards* the values to the assistant. It does not
        authenticate the WebSocket, and returning a token here does not
        restrict who may connect.

        Args:
            request: The HTTP request that opened the WebSocket connection.

        Returns:
            The client-supplied data, or `None` when the client sent nothing.
        """
        metadata: Dict[str, Any] = {}

        authorization = request.headers.get(AUTHORIZATION_HEADER)
        if authorization:
            metadata[AUTHORIZATION_METADATA_KEY] = authorization

        for name in request.args:
            if name != LANGUAGE_QUERY_ARG:
                metadata[name] = request.args.get(name)

        return metadata or None

    async def collect_call_parameters(
        self,
        channel_websocket: Websocket,
        request: Optional[Request] = None,
    ) -> Optional[CallParameters]:
        """Collect call parameters from the WebSocket upgrade request."""
        call_id = f"app-{uuid.uuid4()}"

        language: Optional[str] = None
        extra: Optional[Dict[str, Any]] = None
        if request is not None:
            language = request.args.get(LANGUAGE_QUERY_ARG) or None
            extra = self.get_metadata(request)

        logger.info(
            "websockets_voice.call_started",
            call_id=call_id,
            audio_format=self.audio_format,
            # Log which keys the client sent, never their values: they can
            # carry auth tokens.
            extra_keys=sorted(extra) if extra else [],
        )
        return CallParameters(
            call_id,
            "mobile",
            "mobile",
            stream_id=call_id,
            language=language,
            extra=extra,
        )

    @classmethod
    def from_credentials(
        cls,
        credentials: Optional[Dict[str, Any]],
    ) -> "WebsocketsInputChannel":
        """Create a Websockets Voice input channel from credentials."""
        cls.validate_basic_credentials(credentials)
        new_creds = repack_voice_credentials(credentials or {})
        return cls(**new_creds)

    async def map_input_message(
        self,
        message: Any,
        ws: Websocket,
    ) -> VoiceChannelAction:
        """Map incoming WebSocket messages to voice channel actions."""
        data = json.loads(message)
        if "audio" in data:
            channel_bytes = base64.b64decode(data["audio"])
            audio_bytes = self.channel_bytes_to_rasa_audio_bytes(channel_bytes)
            return NewAudioAction(audio_bytes)
        elif "text" in data:
            text = data["text"]
            if isinstance(text, str) and text:
                return TextInputAction(text=text)
        elif "marker" in data:
            marker_id = data["marker"]

            marker = call_state.get_marker(marker_id)

            if marker:
                call_state.remove_marker(marker.marker_id)
                if marker.step_type:
                    if marker.marker_type == MarkerType.START:
                        call_state.current_bot_utterance_type = marker.step_type
                        await call_state.enqueue_event(BotIsSpeaking())

                    if marker.marker_type == MarkerType.END:
                        call_state.current_bot_utterance_type = None
                        await call_state.enqueue_event(BotStoppedSpeaking())
                        if call_state.should_hangup:
                            logger.debug(
                                "websockets_voice.hangup",
                                marker=marker,
                            )
                            return EndConversationAction()
        return ContinueConversationAction()

    async def interrupt_playback(
        self, ws: Websocket, call_parameters: CallParameters
    ) -> None:
        """Interrupt the current playback of audio."""
        logger.debug("websockets_voice.interrupt_playback")
        await ws.send(json.dumps({"interruptPlayback": True}))

    def create_output_channel(
        self, voice_websocket: Websocket, tts_engine: TTSEngine
    ) -> VoiceOutputChannel:
        """Create a Websockets Voice output channel."""
        logger.debug("websockets_voice.create_output_channel")
        return WebsocketsOutputChannel(
            voice_websocket=voice_websocket,
            audio_format=self.audio_format,
            tts_engine=tts_engine,
            tts_cache=self.tts_cache,
        )

    def conversation_blueprint(
        self,
        agent: RuntimeAgent,
    ) -> Blueprint:
        """Define a Sanic blueprint for the Websockets Voice channel."""
        blueprint = Blueprint("websockets_voice", __name__)

        @blueprint.route("/", methods=["GET"])
        async def health(_: Request) -> HTTPResponse:
            return response.json({"status": "ok"})

        @blueprint.websocket("/websocket")  # type: ignore
        async def handle_message(request: Request, ws: Websocket) -> None:
            try:
                await self.run_audio_streaming(agent, ws, request=request)
            except Exception as e:
                logger.error("websockets_voice.handle_message.error", error=e)

        return blueprint
